     7	import { startErrorReports, type PageErrorReport } from './errorReports';
     8	
     9	export type ConnectionState =
    10	  | 'connecting'
    11	  | 'connected'
    12	  | 'no-transport'
    13	  | 'incompatible'
    14	  | 'timeout';
    15	
    16	export interface Envelope<T = unknown> {
    17	  protocol: string;
    18	  version: number;
    19	  id: string;
    20	  type: string;
    21	  correlationId?: string;
    22	  sessionId?: string;
    23	  revision?: number;
    24	  payload: T;
    25	}
    26	
    27	// Which protocol this page speaks, from its own protocol.json.
    28	export interface ProtocolIdentity {
    29	  name: string;
    30	  version: number;
    31	  capabilities: string[];
    32	}
    33	
    34	export interface Transport {
    35	  post(json: string): void;
    36	}
    37	
    38	export interface BridgeClientOptions {
    39	  // The native transport can appear slightly after the page starts running:
    40	  // wx injects window.wx into an already-loading page from native code. The
    41	  // client therefore re-polls this factory before declaring no-transport.
    42	  getTransport: () => Transport | null;
    43	  onEnvelope: (envelope: Envelope) => void;
    44	  onConnectionChange: (state: ConnectionState, detail?: string) => void;
    45	  handshakeTimeoutMs?: number;
    46	  transportRetryMs?: number;
    47	  transportRetryLimit?: number;
    48	  // Injectable for deterministic tests.
    49	  scheduleTimeout?: (fn: () => void, ms: number) => unknown;
    50	  cancelTimeout?: (handle: unknown) => void;
    51	}
    52	
    53	declare global {
    54	  interface Window {
    55	    wx?: { postMessage(json: string): void };
    56	    __jusprinBridge?: { deliver(envelope: unknown): void };
    57	  }
    58	}
    59	
    60	export function nativeTransport(): Transport | null {
    61	  if (typeof window !== 'undefined' && window.wx && typeof window.wx.postMessage === 'function') {
    62	    return { post: (json) => window.wx!.postMessage(json) };
    63	  }
    64	  return null;
    65	}
    66	
    67	export function envelopeMatches(value: unknown, protocolName: string): value is Envelope {
    68	  if (typeof value !== 'object' || value === null) return false;
    69	  const env = value as Record<string, unknown>;
    70	  return (
    71	    env.protocol === protocolName &&
    72	    typeof env.version === 'number' &&
    73	    typeof env.id === 'string' &&
    74	    typeof env.type === 'string'
    75	  );
    76	}
