    78	export class SharedBridgeClient {
    79	  private readonly protocol: ProtocolIdentity;
    80	  private readonly options: BridgeClientOptions;
    81	  private nextId = 1;
    82	  private handshakeHandle: unknown = null;
    83	  private state: ConnectionState = 'connecting';
    84	  private transport: Transport | null = null;
