   104	      startErrorReports((report) => this.reportError(report));
   105	    }
   106	    this.beginHandshake();
   107	  }
   108	
   109	  retry(): void {
   110	    this.transportAttempts = 0;
   111	    this.beginHandshake();
   112	  }
   113	
   114	  private schedule(fn: () => void, ms: number): unknown {
   115	    const schedule = this.options.scheduleTimeout ?? ((f, m) => setTimeout(f, m));
   116	    return schedule(fn, ms);
   117	  }
   118	
   119	  private cancel(handle: unknown): void {
   120	    const cancel = this.options.cancelTimeout ?? ((h) => clearTimeout(h as number));
   121	    cancel(handle);
   122	  }
   123	
   124	  private beginHandshake(): void {
