   127	      const limit = this.options.transportRetryLimit ?? 40;
   128	      if (this.transportAttempts < limit) {
   129	        this.transportAttempts += 1;
   130	        this.setState('connecting');
   131	        this.schedule(() => {
   132	          if (this.state === 'connecting' && !this.transport) this.beginHandshake();
   133	        }, this.options.transportRetryMs ?? 250);
   134	      } else {
   135	        this.setState('no-transport', 'The native message handler (window.wx) is not present.');
   136	      }
   137	      return;
   138	    }
   139	    this.setState('connecting');
   140	    this.post('hello', {
   141	      protocolVersions: [this.protocol.version],
   142	      capabilities: this.protocol.capabilities,
   143	    });
   144	    const timeoutMs = this.options.handshakeTimeoutMs ?? 10000;
   145	    if (this.handshakeHandle !== null) this.cancel(this.handshakeHandle);
   146	    this.handshakeHandle = this.schedule(() => {
   147	      if (this.state === 'connecting') {
   148	        this.setState('timeout', 'The native host did not answer the hello handshake.');
   149	      }
   150	    }, timeoutMs);
   151	  }
