   153	  reportError(report: PageErrorReport): void {
   154	    if (this.state === 'connected') this.post('report_error', report);
   155	    else this.unsentErrors.push(report);
   156	  }
   157	
   158	  send(type: string, payload: unknown): void {
   159	    this.post(type, payload);
   160	  }
   161	
   162	  private post(type: string, payload: unknown): void {
   163	    if (!this.transport) return;
   164	    const envelope: Envelope = {
   165	      protocol: this.protocol.name,
   166	      version: this.protocol.version,
   167	      id: `w-${this.nextId++}`,
   168	      type,
   169	      payload,
   170	    };
   171	    this.transport.post(JSON.stringify(envelope));
   172	  }
   173	
   174	  deliver(raw: unknown): void {
   175	    if (!envelopeMatches(raw, this.protocol.name)) return; // not this protocol; ignore
   176	    const envelope = raw;
   177	    if (envelope.type === 'hello_ack') {
   178	      this.cancelHandshakeTimer();
   179	      this.setState('connected');
   180	      for (const report of this.unsentErrors.splice(0)) this.post('report_error', report);
   181	    } else if (envelope.type === 'hello_reject') {
   182	      this.cancelHandshakeTimer();
   183	      const payload = envelope.payload as { message?: string } | undefined;
   184	      this.setState('incompatible', payload?.message ?? 'The host rejected this protocol version.');
   185	    }
   186	    this.options.onEnvelope(envelope);
   187	  }
   188	
   189	  private cancelHandshakeTimer(): void {
   190	    if (this.handshakeHandle !== null) {
   191	      this.cancel(this.handshakeHandle);
   192	      this.handshakeHandle = null;
   193	    }
   194	  }
   195	
   196	  private setState(state: ConnectionState, detail?: string): void {
   197	    this.state = state;
   198	    this.options.onConnectionChange(state, detail);
   199	  }
   200	}
